import ast

errors = []
for i in range(len(value["DiffusionBValues"])):
    prefix = "Entry " + str(i) + ": "

    # --- Parse b-values safely ---
    try:
        bvals = as_list(value["DiffusionBValues"][i])
    except Exception:
        bvals = []
        errors.append(prefix + "DiffusionBValues could not be parsed")

    # --- Parse directions safely ---
    try:
        dirs_per_shell = as_list(value["DirectionsPerShell"][i])
    except Exception:
        dirs_per_shell = []

    # --- Rule 1 ---
    try:
        if float(value["NumberOfDiffusionShells"][i]) < 1:
            errors.append(prefix + "At least two distinct b-values (including b=0) must be acquired")
    except Exception:
        errors.append(prefix + "NumberOfDiffusionShells could not be read")

    # --- Rule 2 ---
    if len(bvals) < 2 or len([b for b in bvals if 500 <= b <= 1500]) < 1:
        errors.append(prefix + "Data with a b-value between 500 and 1500 must be acquired")

    # --- Rule 3 ---
    try:
        if float(value["NumberOfB0Volumes"][i]) < 5:
            errors.append(prefix + "[warning] While one non-diffusion-weighted image is sufficient for DTI analysis, it is recommended to acquire minimally 5")
    except Exception:
        errors.append(prefix + "NumberOfB0Volumes could not be read")

    # --- Rule 4 ---
    for j, b in enumerate(bvals):
        if 500 <= b <= 1500 and j < len(dirs_per_shell):
            n_dirs = dirs_per_shell[j]
            if n_dirs < 6:
                errors.append(prefix + "Fewer than 6 diffusion directions for b-value [500-1500]; at least 6 are required")
            elif n_dirs < 30:
                errors.append(prefix + "[warning] Recommended to acquire minimally 30 gradient directions for b-value [500-1500]")

warns = [m for m in errors if "[warning]" in m]
fails = [m for m in errors if "[warning]" not in m]
if fails:
    raise ValidationError(chr(10).join("• " + m for m in fails + warns))
if warns:
    raise ValidationWarning(chr(10).join("• " + m for m in warns))

import ast

# Custom validation logic for Diffusion Kurtosis Imaging (DKI)
# Access field data with value["FieldName"]
# Raise ValidationError for failures; recommendation-level items tagged [warning]

errors = []
for i in range(len(value["DiffusionBValues"])):
    prefix = "Entry " + str(i) + ": "

    # --- Parse array-valued fields safely ---
    try:
        bvals = as_list(value["DiffusionBValues"][i])
    except Exception:
        bvals = []
        errors.append(prefix + "DiffusionBValues could not be parsed")

    try:
        dirs_per_shell = as_list(value["DirectionsPerShell"][i])
    except Exception:
        dirs_per_shell = []

    # --- Rule 1: NumberOfDiffusionShells must be >= 2 ---
    try:
        if float(value["NumberOfDiffusionShells"][i]) < 2:
            errors.append(prefix + "At least two b-shells must be acquired")
    except Exception:
        errors.append(prefix + "NumberOfDiffusionShells could not be read")

    # --- Rule 2: at least 3 b-values (including b=0) must be < 3000 ---
    if len([b for b in bvals if b < 3000]) < 3:
        errors.append(prefix + "At least 3 b-values below 3000 s/mm2 (including b=0) must be acquired for DKI")

    # --- Build shell -> directions mapping (by index alignment) ---
    shells = []
    for j, b in enumerate(bvals):
        n_dirs = dirs_per_shell[j] if j < len(dirs_per_shell) else None
        shells.append((b, n_dirs))

    # --- Rule 3: maximal b-value shell must have >= 15 directions (fail), 30 preferred (warning) ---
    if bvals:
        max_b = max(bvals)
        max_dirs = next((n for b, n in shells if b == max_b and n is not None), None)
        if max_dirs is None:
            errors.append(prefix + "Could not determine gradient directions for the maximal b-value")
        elif max_dirs < 15:
            errors.append(prefix + "The maximal b-value must have at least 15 gradient directions for DKI")
        elif max_dirs < 30:
            errors.append(prefix + "[warning] The maximal b-value has fewer than 30 gradient directions; 30 is recommended for DKI")

    # --- Rule 4: total directions for b>0 data must be >= 21 (fail), 60 preferred (warning) ---
    total_nonzero_dirs = sum(n for b, n in shells if b > 0 and n is not None)
    if total_nonzero_dirs < 21:
        errors.append(prefix + "The total number of gradient directions for b>0 data must be at least 21 for DKI")
    elif total_nonzero_dirs < 60:
        errors.append(prefix + "[warning] The total number of gradient directions for b>0 data is fewer than 60; 60 is recommended for DKI")

warns = [m for m in errors if "[warning]" in m]
fails = [m for m in errors if "[warning]" not in m]
if fails:
    raise ValidationError(chr(10).join("• " + m for m in fails + warns))
if warns:
    raise ValidationWarning(chr(10).join("• " + m for m in warns))

